partner = env.user.partner_id
if partner:
    for rec in records:
        if rec.outreach_mail_sent:
            continue
        env['bus.bus']._sendone(partner, 'sgc_outreach_popup', {
            'action': {
                'type': 'ir.actions.act_window',
                'name': 'Choose Outreach Email — %s' % rec.name,
                'res_model': 'crm.outreach.wizard',
                'views': [[False, 'form']],
                'target': 'new',
                'context': {'default_lead_id': rec.id},
            },
        })
